// A2 · Verify Owner Signature — HMAC-SHA256 over the RAW bytes, constant-time compare.
//
// WHY RAW: the dashboard signs the exact string it sends. If n8n re-serialises the parsed JSON, key order
// and spacing change and a correct signature stops matching — paid for once already on the Zernio inbound.
// _raw_source is reported so a drill can SEE which route supplied the bytes; a silent fallback between two
// routes would hide the day the webhook stops producing binary.
//
// CORRECTED 2026-09-13: this instance has NO global `crypto` (typeof === 'undefined') but DOES have
// require('crypto') since NODE_FUNCTION_ALLOW_BUILTIN=crypto. The build package said the opposite.
const crypto = require('crypto');

const item = $input.first();
let raw = '', src = 'none';
if (item.binary && item.binary.data && item.binary.data.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8'); src = 'binary';
} else if (typeof item.json.body === 'string') {
  raw = item.json.body; src = 'json.body:string';
} else if (item.json.body && typeof item.json.body === 'object') {
  raw = JSON.stringify(item.json.body); src = 'json.body:reserialised';
}

const headers = item.json.headers || {};
const given = headers['x-owner-signature'];
const secret = $env.OWNER_HMAC_SECRET;

let sig_valid = false;
if (typeof secret === 'string' && secret.length > 0 && typeof given === 'string' && raw.length > 0) {
  const mine = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
  // timingSafeEqual THROWS on a length mismatch, so the length is checked first and a wrong-length
  // signature is rejected without ever reaching the comparison.
  if (given.length === mine.length) {
    sig_valid = crypto.timingSafeEqual(Buffer.from(mine, 'utf8'), Buffer.from(given, 'utf8'));
  }
}

// The body is parsed ONLY to carry fields forward. Nothing downstream acts on it before Signature Valid?.
let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
const ts = Number(parsed.ts);
const now = Math.floor(Date.now() / 1000);

return [{ json: {
  sig_valid,
  _raw_source: src,
  // CHOICE, stated rather than left implicit: the window is SYMMETRIC (±300s). A future-dated `ts` is
  // accepted within the same 5 minutes because the dashboard's clock is not ours to trust to the second and
  // a one-sided window turns ordinary clock skew into an unexplainable 401 for the owner. The replay risk a
  // symmetric window adds is bounded by the same 5 minutes and is covered by the messageId dedupe.
  ts_fresh: Number.isFinite(ts) && Math.abs(now - ts) <= 300,
  action: typeof parsed.action === 'string' ? parsed.action : '',
  record_id: typeof parsed.record_id === 'string' ? parsed.record_id : '',
  messageId: typeof parsed.messageId === 'string' ? parsed.messageId : '',
  ts: Number.isFinite(ts) ? ts : null,
} }];

// A5 · Validate Owner Action — THE ALLOW-LIST.
// prompt-injection.md expressed in the engine: there is exactly ONE write verb, so there is nothing for a
// compromise to escalate INTO. It is also why CRT #11 is auditable at all — the surface is one verb.
// Mirrors OWNER_ACTIONS in web/dashboard/lib/ownerAction.ts; a second verb must be added in BOTH places
// deliberately, never inherited.
const OWNER_ACTIONS = ['release_handoff'];

// record_id is signature-verified, so this is not a trust boundary — it is an INJECTION boundary: the value
// is interpolated into an Airtable formula downstream, and a formula built from an unconstrained string is
// the same defect class whatever signed it.
const RECORD_ID = /^rec[A-Za-z0-9]{14}$/;
const MESSAGE_ID = /^[A-Za-z0-9._-]{1,64}$/;   // no quote, brace or paren: nothing that can end a formula string   // Airtable ids are rec + EXACTLY 14; {1,20} was looser than the format it checks

const j = $json;
return [{ json: { ...j,
  // `messageId` is interpolated into an Airtable formula downstream exactly as `record_id` is, and it was
  // only LENGTH-checked — the injection surface closed on one field was left open on the other, in the
  // same expression (Codex CRT #11). CONSTRAIN rather than escape: the id is ours to generate
  // (ReleaseButton emits `d11-<ts>-<rand>`), so a strict character class is a smaller and more checkable
  // contract than a quoting routine, and a future caller cannot forget to apply it.
  action_allowed: OWNER_ACTIONS.includes(j.action) && RECORD_ID.test(j.record_id) && MESSAGE_ID.test(j.messageId),
} }];

// A7 · Validate Release Target — a correct signature does not say WHICH conversation.
// ARCH-DEC (2026-09-03) names the threat: "an unsigned owner-action endpoint would let anyone unlock any
// conversation" — a SIGNED one with no target check has the same hole for anyone holding the secret.
// Three conditions, all required: the record exists · stage === 'handoff' · it was touched recently.
const MAX_AGE_DAYS = 30;

const ctx = $('Validate Owner Action').first().json;
const rows = $input.all().filter(i => i.json && i.json.id && !i.json.error);
const row = rows[0] ? rows[0].json : null;
const f = row ? (row.fields || row) : {};

const found = !!row;
const stage = typeof f.stage === 'string' ? f.stage : '';
const lu = f.last_updated ? Date.parse(f.last_updated) : NaN;
// ⚠ The comment said "touched within 30 days" and the arithmetic did not: `Date.now() - lu <= 30d` is
// TRUE for ANY future timestamp, so `last_updated = 2099` unlocked a row the window existed to exclude
// (Codex CRT #11). The age must be NON-NEGATIVE and within the window; a small forward tolerance covers
// ordinary clock skew instead of pretending clocks agree. Comment and code say the same thing now.
const CLOCK_SKEW_MS = 5 * 60 * 1000;
const age = Number.isFinite(lu) ? (Date.now() - lu) : NaN;
const fresh = Number.isFinite(age) && age >= -CLOCK_SKEW_MS && age <= MAX_AGE_DAYS * 86400000;

return [{ json: { ...ctx,
  target_found: found,
  target_locked: found && stage === 'handoff' && fresh,
  target_record: found ? row.id : '',
  // stage is carried for the alert text only; no customer content crosses this node.
  target_stage: stage,
} }];

// A8 · Owner replay check — booking-integrity.md item 1: the same click twice must produce ONE write.
//
// ⚠ MEASURED BOUND, stated rather than overclaimed: Record Owner Action Processed writes at the END, so a
// replay arriving while the first is still IN FLIGHT finds nothing and proceeds. On the booking path a
// deterministic calendar event id absorbs that; HERE THERE IS NO SUCH BACKSTOP. What makes it safe is that
// the write is idempotent — setting stage='new' twice equals once. Do not write "deduplicated" on a sticky.
const ctx = $('Validate Release Target').first().json;
// ⚠ FAIL-CLOSED ON A LOOKUP ERROR (Codex CRT #11). This filtered error items away, so a FAILED search read
// as "not a replay" — and the node runs with continueRegularOutput, meaning an Airtable outage would have
// waved a duplicate straight through to the write. A lookup failure is not a refusal and it is not an
// all-clear: it is UNCERTAINTY, and `handoff.md` is explicit that we do not act on what we distrust.
const items = $input.all();
const errored = items.some(i => i.json && i.json.error);
const hits = items.filter(i => i.json && i.json.id && !i.json.error);
return [{ json: { ...ctx, replay_lookup_failed: errored,
                  is_replay: errored ? true : hits.length > 0 } }];

// B4 · the dedupe marker did not get written. The RELEASE succeeded, so this is not a failure — but it is
// not a plain success either: without the marker the replay guard has no record, and the same messageId can
// write again. Reporting `{ok:true}` here would close idempotency SILENTLY, which is the one thing
// `booking-integrity.md` does not allow a write path to do.
const ctx = $('Owner Replay Seen?').first().json;
const esc = (t) => String(t).replace(/[_*`\[\]~]/g, '-');
return [{ json: {
  _alert_class: 'handoff_release_marker_unwritten',
  owner_alert_text: esc('⚠ Handoff released, but the dedupe marker was NOT written\n'
    + 'conversation: ' + String(ctx.target_record || '').slice(0, 3) + '…\n'
    + 'the lock IS open; a repeat of the same click would write again\n'
    + 'at: ' + new Date().toISOString()),
} }];

// Telegram parses Markdown by default and a lone `_` opened an entity that never closed: the send came
// back "can't parse entities" and the alert vanished while the caller still got 200 (exec 2761).
// This is the SAME transform the Main, Reminders and Purge builders have carried all along — copied
// deliberately rather than re-solved, because a second escaping strategy is a second truth that drifts.
const esc = (t) => String(t).replace(/[_*`\[\]~]/g, '-');
// A11 · Build Owner Alert (Release) — class `handoff_released`.
// An owner-initiated WRITE that leaves no trace is the one kind nobody can audit afterwards.
// No customer content and no full record id in the text: an alert lands in a third-party chat log.
const ctx = $('Owner Replay Seen?').first().json;
return [{ json: {
  _alert_class: 'handoff_released',
  _alert_at: new Date().toISOString(),
  owner_alert_text: esc('🔓 Handoff released from the dashboard\n'
    + 'conversation: ' + String(ctx.target_record || '').slice(0, 3) + '…\n'
    + 'stage: handoff → new (last_intent cleared)\n'
    + 'at: ' + new Date().toISOString()),
} }];

// TERMINAL by design — an alert about a failed alert is the infinite loop Codex INVARIANT #1 names.
// It exists so a delivery failure is VISIBLE on the canvas and in the execution instead of vanishing into
// the success path, which is exactly how exec 2761 returned 200 while nothing reached the owner.
// It still responds: the RELEASE succeeded, and leaving the caller to time out would turn a delivered
// write into an apparent outage.
return [{ json: { _alert_delivery_failed: true } }];

// Telegram parses Markdown by default and a lone `_` opened an entity that never closed: the send came
// back "can't parse entities" and the alert vanished while the caller still got 200 (exec 2761).
// This is the SAME transform the Main, Reminders and Purge builders have carried all along — copied
// deliberately rather than re-solved, because a second escaping strategy is a second truth that drifts.
const esc = (t) => String(t).replace(/[_*`\[\]~]/g, '-');
// The release path's FAILURE alert — a separate class, deliberately not merged with the success one.
// handoff.md: an infrastructure failure must never be indistinguishable from a normal outcome.
// ⚠ This leaf is TERMINAL — no alert about a failed alert (Codex INVARIANT #1, infinite loop).
const ctx = $('Owner Replay Seen?').first().json;
return [{ json: {
  _alert_class: 'handoff_release_failed',
  owner_alert_text: esc('⚠ Handoff release FAILED (dashboard)\n'
    + 'conversation: ' + String(ctx.target_record || '').slice(0, 3) + '…\n'
    + 'the lock was NOT opened — the owner saw an error and the row is unchanged or half-written\n'
    + 'at: ' + new Date().toISOString()),
} }];
